package gitrepo

import (
	"context"
	"errors"
	"fmt"
	"os/exec"
	"strings"
	"time"

	"github.com/go-git/go-git/v6/plumbing"
)

// WorktreeContentHashBudget bounds native Git clean-filter processing on the
// hook paths that compare the working tree with a commit: post-commit
// carry-forward, and the turn-end and subagent-capture committed-file filter.
// A broken or hanging custom filter must not leave the hook process blocked
// indefinitely.
const WorktreeContentHashBudget = 5 * time.Second

// HashWorktreeFiles returns the Git blob hash of each regular working-tree file
// after applying Git's path-specific clean filters. Git hash-object follows
// symlinks, so callers comparing Git symlink blobs must handle those separately.
// Large path sets are split across commands so an oversized argv cannot fail
// before Git inspects anything.
//
// The paths must be repository-relative. They are file operands, not pathspecs,
// so names containing pathspec magic are interpreted literally. The returned
// map can contain successful hashes alongside a non-nil error; callers can
// retain filter-aware results and degrade only the files Git could not hash.
func HashWorktreeFiles(
	ctx context.Context,
	worktreeRoot string,
	paths []string,
) (map[string]plumbing.Hash, error) {
	ctx, cancel := context.WithTimeout(ctx, WorktreeContentHashBudget)
	defer cancel()
	return hashWorktreeFiles(ctx, worktreeRoot, paths, gitHashObjectPathBudget)
}

func hashWorktreeFiles(
	ctx context.Context,
	worktreeRoot string,
	paths []string,
	pathBudget int,
) (map[string]plumbing.Hash, error) {
	hashes := make(map[string]plumbing.Hash, len(paths))
	var errs []error
	for _, batch := range chunkPaths(paths, pathBudget) {
		batchHashes, err := hashWorktreeFileBatch(ctx, worktreeRoot, batch)
		if err == nil {
			for i, path := range batch {
				hashes[path] = batchHashes[i]
			}
			continue
		}

		// A missing or unreadable file fails the whole hash-object invocation.
		// Retry that batch one file at a time so its neighbours keep their
		// filter-aware hashes instead of all dropping to the raw-byte fallback.
		var exitErr *exec.ExitError
		if len(batch) == 1 || ctx.Err() != nil || !errors.As(err, &exitErr) {
			errs = append(errs, err)
			continue
		}
		for _, path := range batch {
			pathHashes, pathErr := hashWorktreeFileBatch(ctx, worktreeRoot, []string{path})
			if pathErr != nil {
				errs = append(errs, pathErr)
				continue
			}
			hashes[path] = pathHashes[0]
		}
	}
	return hashes, errors.Join(errs...)
}

func hashWorktreeFileBatch(ctx context.Context, worktreeRoot string, paths []string) ([]plumbing.Hash, error) {
	args := []string{"-C", worktreeRoot, "hash-object", "--"}
	args = append(args, paths...)
	cmd := exec.CommandContext(ctx, "git", args...)
	cmd.Env = EnvWithoutRepoOverrides()
	out, err := cmd.Output()
	if err != nil {
		var exitErr *exec.ExitError
		if errors.As(err, &exitErr) {
			if stderr := strings.TrimSpace(string(exitErr.Stderr)); stderr != "" {
				return nil, fmt.Errorf("git hash-object: %w: %s", err, stderr)
			}
		}
		return nil, fmt.Errorf("git hash-object: %w", err)
	}

	fields := strings.Fields(string(out))
	if len(fields) != len(paths) {
		return nil, fmt.Errorf("git hash-object returned %d hashes for %d paths", len(fields), len(paths))
	}
	hashes := make([]plumbing.Hash, len(fields))
	for i, field := range fields {
		if !plumbing.IsHash(field) {
			return nil, fmt.Errorf("git hash-object returned invalid hash %q", field)
		}
		hashes[i] = plumbing.NewHash(field)
	}
	return hashes, nil
}

// Keep path argv comfortably below Windows' 32 KiB command-line limit,
// including room for fixed arguments and os/exec quoting. Unix limits are much
// larger. A single repository-relative path can exceed the budget and is sent
// alone; filesystem path limits still keep that command bounded.
const gitHashObjectPathBudget = 8 * 1024

func chunkPaths(paths []string, budget int) [][]string {
	var chunks [][]string
	var (
		chunk []string
		size  int
	)
	for _, path := range paths {
		if len(chunk) > 0 && size+len(path)+1 > budget {
			chunks = append(chunks, chunk)
			chunk = nil
			size = 0
		}
		chunk = append(chunk, path)
		size += len(path) + 1
	}
	if len(chunk) > 0 {
		chunks = append(chunks, chunk)
	}
	return chunks
}
	}

	logCtx := logging.WithComponent(ctx, "filter-uncommitted")

	// relPath comes from git, so it is already the coordinate both the tree
	// lookup and the working-tree hash read in.
	committed := make(map[string]*object.File, len(files))
	for _, relPath := range files {
		headFile, fileErr := headTree.File(relPath)
		if fileErr != nil {
			logging.Debug(logCtx, "file not in HEAD tree, keeping",
				slog.String("file", relPath),
				slog.String("error", fileErr.Error()))
			continue
		}
		committed[relPath] = headFile
	}
	matches := strategy.WorktreeMatchesCommitted(logCtx, repoRoot, committed)

	var result []string
	for _, relPath := range files {
		if !matches[relPath] {
			result = append(result, relPath)
		}
	}

	return result
}

// FilterAndNormalizePaths converts absolute paths to relative and filters out
// infrastructure paths and paths outside the repo.
func FilterAndNormalizePaths(files []string, cwd string) []string {
	var result []string
	for _, file := range files {
		relPath := paths.ToRelativePath(file, cwd)
		if relPath == "" {
			continue // outside repo
		}
		if shouldIgnoreSessionTrackingPath(relPath) {
			continue
		}
		result = append(result, filepath.ToSlash(relPath))
	}
	return result
}

// mergeUnique appends elements from extra into base, skipping duplicates already in base.
func mergeUnique(base, extra []string) []string {
	if len(extra) == 0 {
		return base
	}
	seen := make(map[string]bool, len(base))
	for _, s := range base {
		seen[s] = true
	}
	for _, s := range extra {
		if !seen[s] {
			seen[s] = true
			base = append(base, s)
		}
	}
	return base
}

// entireTmpName is .entire/tmp expressed relative to the .entire root, which is
// the coordinate every read and write below uses.
var entireTmpName = entiredir.MustName(paths.EntireTmpDir)

// tmpFile formats a state file name relative to the .entire root. The format
// arguments are already-validated session and tool-use IDs; the root confines
// the resulting open regardless.
func tmpFile(format string, args ...any) string {
	return entireTmpName + "/" + fmt.Sprintf(format, args...)
}

// sessionMetadataName returns a session's metadata directory relative to the
// .entire root. sessionID reaches here from agent hook input; callers validate
// it, and the root confines the open either way.
func sessionMetadataName(sessionID string) string {
	return entiredir.MustName(paths.SessionMetadataDirFromSessionID(sessionID))
}

// openTmpDir returns the shared .entire root with tmp/ created under it, for
// the capture paths that are about to write a state file.
func openTmpDir(ctx context.Context) (*os.Root, error) {
	root, err := entiredir.Open(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to open %s: %w", paths.EntireDir, err)
	}
	if err := osroot.MkdirAllNoSymlink(root, entireTmpName, 0o750); err != nil {
		return nil, fmt.Errorf("failed to create tmp directory: %w", err)
	}
	return root, nil
}

// untrackedFilesOrSkip runs the pre-prompt/pre-task untracked scan, degrading
// instead of failing. Deliberately wider than the status-budget feature that
// introduced it: EVERY scan error fails open — budget breach, repo-open
// failure, corrupted .git, anything — because these captures run inside
// TurnStart/SubagentStart hooks, and any error propagated from here used to
// fail the hook and break the agent's turn. That fail-hook behavior was the
// bug, not a safety property: the scan only feeds new-file detection, so the
// correct degrade is to warn, mark the scan skipped (the paired end-hook then
// disables new-file detection for the turn), and let capture proceed with
// transcript-derived data.
func untrackedFilesOrSkip(ctx context.Context) (untrackedFiles []string, scanSkipped bool) {
}

// WorktreeMatchesCommitted reports, per path, whether the working tree still
// holds the content the commit holds, judged the way `git status` judges it.
// Native hash-object applies the path's clean filters (core.autocrlf, LFS,
// ident), so a CRLF working copy of an LF-normalized blob matches. Raw bytes
// equal to the blob match too: git exempts a blob that already carries CRLF
// from autocrlf conversion, while hash-object converts unconditionally, so the
// filtered hash alone would call such a file dirty. Symlink blobs and paths Git
// cannot hash take the confined raw comparison only, because hash-object
// follows a link and hashes the target's content while the blob stores the
// target path. Modes are not compared: an executable-bit-only change reads as
// committed. An empty worktreeRoot matches nothing. Warnings are logged on ctx,
// so callers pass the context carrying their component.
func WorktreeMatchesCommitted(ctx context.Context, worktreeRoot string, files map[string]*object.File) map[string]bool {
	matches := make(map[string]bool, len(files))
	if worktreeRoot == "" || len(files) == 0 {
		return matches
	}

	paths := make([]string, 0, len(files))
	for path, file := range files {
		if !requiresConfinedWorktreeHash(worktreeRoot, path, file.Mode) {
			paths = append(paths, path)
		}
	}
	worktreeHashes, err := gitrepo.HashWorktreeFiles(ctx, worktreeRoot, paths)
	if err != nil {
		logging.Warn(ctx, "native git could not hash every working-tree candidate; checking failed paths conservatively without clean filters",
			slog.String("error", err.Error()),
		)
	}

	for path, file := range files {
		if worktreeHash, ok := worktreeHashes[path]; ok && worktreeHash == file.Hash {
			matches[path] = true
			continue
		}
		matches[path] = workingTreeMatchesBlob(worktreeRoot, path, file.Mode, file.Hash)
	}
	return matches
}

func requiresConfinedWorktreeHash(worktreeRoot, filePath string, commitMode filemode.FileMode) bool {
	if commitMode == filemode.Symlink {
		return true
	}
	root, err := worktreedir.OpenAt(worktreeRoot)
	if err != nil {
		return true
	}
	name, err := worktreedir.Name(worktreeRoot, filePath)
	if err != nil {
		return true
	}
	info, err := root.Lstat(name)
	return err != nil || requiresConfinedWorktreeMode(info.Mode())
}

func requiresConfinedWorktreeMode(mode fs.FileMode) bool {
	// Windows uses ModeIrregular for OneDrive Files On-Demand placeholders.
	// Mask it so placeholder files still receive Git's clean-filter handling,
	// while every substantive non-regular type remains confined.
	return mode.Type()&^fs.ModeIrregular != 0
}

// workingTreeMatchesBlob checks whether the raw file representation hashes to
// commitHash. It is the filter-unaware fallback for when native Git cannot hash
// a regular file and the symlink-aware path for Git symlink blobs.
func workingTreeMatchesBlob(worktreeRoot, filePath string, commitMode filemode.FileMode, commitHash plumbing.Hash) bool {
	root, err := worktreedir.OpenAt(worktreeRoot)
	if err != nil {
		return false
	}
	name, err := worktreedir.Name(worktreeRoot, filePath)
	if err != nil {
		return false
	}
	var diskContent []byte
	if commitMode == filemode.Symlink && isSymlinkOnDisk(root, name) {
		target, readErr := root.Readlink(name)
		if readErr != nil {
			return false
		}
		diskContent = []byte(target)
	} else {
		// Under core.symlinks=false git checks a symlink blob out as a regular
		// file holding the link text and keeps mode 120000 on add, so the raw
		// bytes are what the blob stores.
		diskContent, err = osroot.ReadFileNoFollow(root, name)
		if err != nil {
			return false
		}
	}
	of := config.SHA1
	if commitHash.Size() == config.SHA256.Size() {
		of = config.SHA256
	}
	h := plumbing.NewHasher(of, plumbing.BlobObject, int64(len(diskContent)))
	if _, err := h.Write(diskContent); err != nil {
		return false
	}
	return commitHash.Equal(h.Sum())
}

func isSymlinkOnDisk(root *os.Root, name string) bool {
	info, err := root.Lstat(name)
	return err == nil && info.Mode()&fs.ModeSymlink != 0
}

